// src/utils/codeCommand.ts
async function executeCodeCommand(args = []) {
  const config2 = await readConfigFile();
  const env = {
    ...process.env,
    ANTHROPIC_AUTH_TOKEN: config2?.APIKEY || "test",
    ANTHROPIC_API_KEY: "",
    ANTHROPIC_BASE_URL: `http://127.0.0.1:${config2.PORT || 4567}`,
    API_TIMEOUT_MS: String(config2.API_TIMEOUT_MS ?? 6e5)
    // Default to 10 minutes if not set
  };
  let settingsFlag;
  if (config2?.StatusLine?.enabled) {
    settingsFlag = {
      statusLine: {
        type: "command",
        command: "ccr2 statusline",
        padding: 0
      }
    };
    args.push(`--settings=${JSON.stringify(settingsFlag)}`);
  }
  if (config2.NON_INTERACTIVE_MODE) {
    env.CI = "true";
    env.FORCE_COLOR = "0";
    env.NODE_NO_READLINE = "1";
    env.TERM = "dumb";
  }
  if (config2?.ANTHROPIC_SMALL_FAST_MODEL) {
    env.ANTHROPIC_SMALL_FAST_MODEL = config2.ANTHROPIC_SMALL_FAST_MODEL;
  }
  incrementReferenceCount();
  const claudePath = config2?.CLAUDE_PATH || process.env.CLAUDE_PATH || "claude";
  const joinedArgs = args.length > 0 ? args.map((arg) => `"${arg.replace(/\"/g, '\\"')}"`).join(" ") : "";
  const stdioConfig = config2.NON_INTERACTIVE_MODE ? ["pipe", "inherit", "inherit"] : "inherit";
  const claudeProcess = (0, import_child_process3.spawn)(
    claudePath + (joinedArgs ? ` ${joinedArgs}` : ""),
    [],
    {
      env,
      stdio: stdioConfig,
      shell: true
    }
  );
  if (config2.NON_INTERACTIVE_MODE) {
    claudeProcess.stdin?.end();
  }
  claudeProcess.on("error", (error) => {
    console.error("Failed to start claude command:", error.message);
    console.log(
      "Make sure Claude Code is installed: npm install -g @anthropic-ai/claude-code"
    );
    decrementReferenceCount();
    process.exit(1);
  });
  claudeProcess.on("close", (code) => {
    decrementReferenceCount();
    closeService();
    process.exit(code || 0);
  });
}

